export class FakeTaskRepository implements TaskRepository {
  readonly items = new Map<string, TaskRecord>()

  async findById(id: string) { return this.items.get(id) ?? null }
  async findScopedById(id: string, _userId: string) { return this.items.get(id) ?? null }

  async listScoped(_userId: string, query: TaskListQuery): Promise<PaginatedTasks> {
    const all = [...this.items.values()]
    const start = (query.page - 1) * query.pageSize
    const data = all.slice(start, start + query.pageSize)
    const totalItems = all.length
    const totalPages = Math.ceil(totalItems / query.pageSize)
    return { data, meta: { page: query.page, pageSize: query.pageSize, totalItems, totalPages, hasPreviousPage: query.page > 1, hasNextPage: query.page < totalPages } }
  }

